"use client";

import { useState } from "react";
import Link from "next/link";
import { Badge, Frame, Title } from "../ui";
const partners = [["OSF", "Open Society Foundations", "Global", "Foundation", "Human Rights · Digital Rights", "2018"], ["ACA", "Africa Climate Alliance", "Sub-Saharan Africa", "Network", "Climate Justice · Research", "2021"], ["NEC", "New Economy Coalition", "Northern Europe", "Network", "Economic Justice · Policy", "2019"], ["HRI", "Health Rights Initiative", "Sub-Saharan Africa", "NGO", "Public Health · Equality", "2022"]];
export default function DirectoryPage() { const [query, setQuery] = useState(""); const visible = partners.filter((partner) => partner[1].toLowerCase().includes(query.toLowerCase())); return <Frame role="OAK Staff"><main className="mx-auto max-w-6xl px-5 py-10"><Title eyebrow="Our network" title="Partner directory" description="Meet the organisations building a more just and open world." /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search organisations, focus areas..." className="h-13 w-full rounded-2xl border-0 bg-white px-5 text-sm shadow-sm ring-1 ring-slate-200 outline-none focus:ring-2 focus:ring-emerald-500" /><div className="mt-4 flex gap-2 overflow-auto">{["All Regions", "Global", "Sub-Saharan Africa", "Northern Europe", "Middle East & North Africa"].map((region) => <button key={region} className="whitespace-nowrap rounded-full bg-white px-4 py-2 text-xs font-bold text-slate-600 ring-1 ring-slate-200">{region}</button>)}</div><div className="mt-8 flex items-center gap-4 overflow-auto border-y border-slate-200 py-5"><span className="whitespace-nowrap text-xs font-bold uppercase tracking-wider text-slate-400">Sub-partners</span>{["OSF", "ACA", "NEC", "HRI", "CJP", "EJF"].map((item) => <span key={item} className="grid h-11 w-11 shrink-0 place-items-center rounded-full bg-[#182c53] text-[10px] font-bold text-white">{item}</span>)}</div><div className="mt-8 grid gap-4 md:grid-cols-2">{visible.map((partner) => <Link href={`/directory/${partner[0].toLowerCase()}`} key={partner[0]} className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex gap-4"><span className="grid h-14 w-14 shrink-0 place-items-center rounded-2xl bg-emerald-100 font-bold text-emerald-800">{partner[0]}</span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-start justify-between gap-2"><h2 className="font-bold">{partner[1]}</h2><Badge>{partner[3]}</Badge></div><p className="mt-1 text-xs text-slate-500">{partner[2]} · Partner since {partner[5]}</p><p className="mt-4 text-xs font-semibold text-emerald-700">{partner[4]}</p></div></div></Link>)}</div></main></Frame>; }
